set-header.value:
@{
var url = context.Request.OriginalUrl;
var port = url.Port == 80 || url.Port == 443 ? "" : ":" + url.Port.ToString();
var origin = url.Scheme + "://" + url.Host + port;
var metadata = origin + "/.well-known/oauth-protected-resource/mosaic/mcp/weather/mcp";
return "Bearer resource_metadata=\"" + metadata + "\"";
}

when.condition:
@{
var values = context.Request.Headers["Authorization"];
if (values == null || values.Length != 1) { return true; }
var authorization = values[0];
return String.IsNullOrWhiteSpace(authorization) || !authorization.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase) || String.IsNullOrWhiteSpace(authorization.Substring(7));
}

set-header.value:
@{
var url = context.Request.OriginalUrl;
var port = url.Port == 80 || url.Port == 443 ? "" : ":" + url.Port.ToString();
var origin = url.Scheme + "://" + url.Host + port;
var metadata = origin + "/.well-known/oauth-protected-resource/mosaic/mcp/weather/mcp";
return "Bearer error=\"invalid_token\", resource_metadata=\"" + metadata + "\"";
}

set-variable.value:
@{
if (!context.Request.Headers.ContainsKey("x-mosaic-cost-center")) { return ""; }
var values = context.Request.Headers["x-mosaic-cost-center"];
if (values == null || values.Length != 1 || values[0] == null) { return "!"; }
var code = values[0].Trim();
if (!System.Text.RegularExpressions.Regex.IsMatch(code, "^[A-Za-z0-9._-]\u007b1,64\u007d$")) { return "!"; }
return code.ToLowerInvariant();
}

@{
var jwt = context.Variables.ContainsKey("mosaic-validated-token") ? context.Variables["mosaic-validated-token"] as Jwt : null;
if (jwt == null || jwt.Claims == null || !jwt.Claims.ContainsKey("oid")) { return ""; }
var values = jwt.Claims["oid"];
if (values == null || values.Length != 1 || String.IsNullOrWhiteSpace(values[0])) { return ""; }
return values[0].ToLowerInvariant();
}

@{
