if (jwt == null || jwt.Claims == null || !jwt.Claims.ContainsKey("azp")) { return ""; }
var values = jwt.Claims["azp"];
if (values == null || values.Length != 1 || String.IsNullOrWhiteSpace(values[0])) { return ""; }
