@{
var jwt = context.Variables.ContainsKey("mosaic-validated-token") ? context.Variables["mosaic-validated-token"] as Jwt : null;
if (jwt == null || jwt.Claims == null || !jwt.Claims.ContainsKey("oid")) { return ""; }
var objects = jwt.Claims["oid"];
if (objects == null || objects.Length != 1 || String.IsNullOrWhiteSpace(objects[0])) { return ""; }
var oid = objects[0];
var cc = (string)context.Variables["mosaic-cc"];
bool delegated = false;
bool application = false;
bool hasRealScopes = false;
if (jwt.Claims.ContainsKey("scp")) {
    var scopes = jwt.Claims["scp"];
    if (scopes != null && scopes.Length == 1 && scopes[0] != null) {
        foreach (var scope in scopes[0].Split(' ')) {
            if (String.IsNullOrWhiteSpace(scope) || scope == "/") { continue; }
            hasRealScopes = true;
            if (String.Equals(scope, "Mcp.Invoke", StringComparison.Ordinal)) { delegated = true; }
        }
    }
}
if (!hasRealScopes && jwt.Claims.ContainsKey("roles")) {
    var roles = jwt.Claims["roles"];
    application = roles != null && roles.Contains("Mcp.Invoke.Application");
}
if (delegated && String.Equals(oid, "00000001-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "general")) { return "e32fdfda1a02e656eac0ffb75fc6fedbc87e7dbeb64a67a5e0f112ae47192142|general"; }
if (delegated && String.Equals(oid, "00000001-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "research")) { return "2fafec527b48075259b75f9d2c438cb39b21fb04ba0eea598130f537a466b5b5|research"; }
return "";
}

@{
var match = (string)context.Variables["mosaic-token-match"];
var bar = match.IndexOf('|');
return bar < 0 ? match : match.Substring(0, bar);
}

@{
var match = (string)context.Variables["mosaic-token-match"];
var bar = match.IndexOf('|');
return bar < 0 ? "" : match.Substring(bar + 1);
}

set-header.value:
@{
var url = context.Request.OriginalUrl;
var port = url.Port == 80 || url.Port == 443 ? "" : ":" + url.Port.ToString();
var origin = url.Scheme + "://" + url.Host + port;
var metadata = origin + "/.well-known/oauth-protected-resource/mosaic/mcp/weather/mcp";
return "Bearer error=\"insufficient_scope\", scope=\"api://22222222-2222-2222-2222-222222222222/Mcp.Invoke\", resource_metadata=\"" + metadata + "\"";
}

set-variable.value:
@{
var code = (string)context.Variables["mosaic-cost-center"];
if (code == "general") { return "costCenter-general"; }
if (code == "research") { return "costCenter-research"; }
return "";
}
